package br.com.saulo.rumoaotaf;
import org.json.*;import java.util.*;

final class PersonalizedTraining {
 private static boolean protectedStart(Planner.Profile p){return p.health.equals("joint")||p.age>=65||p.weight/Math.pow(p.height/100,2)>=35;}
 private static int level(Planner.Profile p){return protectedStart(p)?0:p.experience.equals("beginner")||p.activity.equals("low")?1:p.activity.equals("light")?2:3;}
 private static List<Integer> days(Planner.Profile p){int[][] map={{},{1},{1,4},{0,3,5},{0,1,3,5},{0,1,3,4,5},{0,1,2,3,4,5}};List<Integer> out=new ArrayList<>();for(int d:map[p.frequency])out.add(d);if(p.swim&&!out.contains(5))out.set(out.size()-1,5);return out;}
 private static List<Integer> strength(Planner.Profile p,List<Integer> days){
  int[] counts=p.goal.equals("strength")?new int[]{0,1,2,2,3,3,3}:new int[]{0,1,1,2,2,2,3};int desired=counts[p.frequency];if(protectedStart(p))desired=Math.min(2,desired);int[] preferred=p.goal.equals("strength")?new int[]{0,3,5}:new int[]{1,4,0};
  List<Integer> possible=new ArrayList<>();for(int d:days)if(!(p.swim&&d==5))possible.add(d);
  for(int count=Math.min(desired,possible.size());count>=0;count--){List<Integer> best=null;int scoreBest=-1;for(int mask=0;mask<(1<<possible.size());mask++){if(Integer.bitCount(mask)!=count)continue;List<Integer> selected=new ArrayList<>();boolean valid=true;int score=0;for(int i=0;i<possible.size();i++)if((mask&(1<<i))!=0){int d=possible.get(i);for(int prev:selected)if(d-prev==1)valid=false;selected.add(d);for(int j=0;j<preferred.length;j++)if(d==preferred[j])score+=10-j;}if(valid&&score>scoreBest){scoreBest=score;best=selected;}}if(best!=null)return best;}return new ArrayList<>();
 }
 static JSONArray reasons(Planner.Profile p){JSONArray a=new JSONArray();int l=level(p);a.put(p.frequency+" treino(s) por semana e "+(7-p.frequency)+" dia(s) de descanso.");a.put(protectedStart(p)?"Começo conservador: duração menor e movimentos apoiados pelo histórico articular, idade ou relação peso/altura.":l>=2?"Experiência regular e atividade informada permitem sessões um pouco mais longas.":"Iniciante, retorno ou rotina pouco ativa: sessões curtas, sem corrida ou saltos.");a.put(p.goal.equals("strength")?"Prioridade em força, com sessões separadas por recuperação.":p.goal.equals("taf")?"Base para TAF: resistência aeróbica, empurrar e controle do tronco, sem presumir índices ou prontidão para corrida.":p.goal.equals("lose")?"Caminhadas para constância e força acompanhando a perda de peso.":"Equilíbrio entre condicionamento, força e recuperação.");a.put(p.place.equals("gym")?"Aparelhos com ajuste orientado pelo instrutor.":"Movimentos em casa com parede, cadeira e apoios firmes.");if(p.swim)a.put("Natação no sábado porque você declarou domínio, acesso e preferência.");if(p.frequency<=2)a.put("Com poucas sessões, força e caminhada podem compartilhar o dia. A frequência escolhida não cobre uma preparação completa.");return a;}
 private static JSONObject step(String name,String dose,String detail)throws JSONException{return new JSONObject().put("name",name).put("dose",dose).put("detail",detail);}
 static JSONArray generate(JSONObject c,Planner.Profile p,Planner.Decision d)throws JSONException{
  List<Integer> days=days(p),strength=strength(p,days);int level=level(p),base=new int[]{12,15,22,30}[level],growth=level==0?2:3;boolean regular=level>=2,protect=protectedStart(p);JSONArray weeks=new JSONArray();
  for(int w=0;w<4;w++){JSONArray week=new JSONArray();for(int day=0;day<7;day++){
   JSONObject t=new JSONObject();JSONArray steps=new JSONArray();String kind;String title,effort=regular?"Confortável · 3–5 de 10":"Leve · 2–3 de 10";int minutes=0;
   if(!days.contains(day)){kind="rest";title="Descanso e recuperação";effort="Sem meta de esforço";steps.put(step("Recupere-se","Dia sem treino","Sono e recuperação. Movimentos suaves se estiver confortável; não é obrigatório treinar hoje."));}
   else if(!d.exerciseAllowed){kind="guide";title="Plano profissional antes de treinar";effort="Sem treino automático";steps.put(step("Converse com um profissional","Avaliação individual",d.exerciseReason));}
   else {
    kind=day==5&&p.swim?"swim":strength.contains(day)?"strength":"walk";
    if(kind.equals("walk")){minutes=Math.min(p.goal.equals("strength")?28:42,base+w*growth+(p.goal.equals("taf")&&regular?3:0));title=p.goal.equals("strength")?"Caminhada de recuperação":p.goal.equals("taf")?"Base aeróbica para TAF":p.goal.equals("lose")?"Caminhada para constância":"Condicionamento e mobilidade";boolean brisk=regular&&!protect&&(p.goal.equals("taf")||p.goal.equals("maintain")&&day==3);steps.put(step("Comece devagar","5 min","Terreno plano e regular, sem mudanças rápidas de direção."));steps.put(step(brisk?"Alternância de caminhada confortável":"Caminhada contínua confortável",(minutes-10)+" min",brisk?"Alterne 2 minutos confortáveis e 1 minuto um pouco mais vivo. Continue conseguindo conversar. Sem corrida.":"Ritmo em que consiga conversar. Faça pausas e reduza a duração se precisar."));steps.put(step("Desacelere e observe","5 min","Só avance de semana se estiver bem durante a atividade e no dia seguinte."));}
    else if(kind.equals("swim")){minutes=(protect?15:regular?25:20)+w*2;title=p.goal.equals("taf")?"Base aquática para TAF":"Natação leve e técnica";steps.put(step("Adapte-se à água","5 min","Piscina supervisionada. Nunca treine sozinho."));steps.put(step(p.goal.equals("taf")?"Técnica e trechos curtos":"Trechos confortáveis com pausas",(minutes-10)+" min com pausas","Sem meta de velocidade. Descanse 30–60 s ou mais. Ajuste pernadas e viradas se houver sintomas articulares."));steps.put(step("Finalize devagar","5 min","Sem apneia, hiperventilação ou simulado máximo. Observe a recuperação."));}
    else {
     int variant=strength.indexOf(day)%2,sets=level==0?1:regular?p.goal.equals("strength")&&w>=2?3:2:w>=2?2:1,reps=regular?p.goal.equals("strength")?8:10:6;minutes=(protect?16:regular?28:20)+(sets>1?4:0)+(p.frequency<=2?5:0);title=(p.goal.equals("taf")?"Força de base para TAF":p.goal.equals("strength")?"Força progressiva":p.goal.equals("lose")?"Força para acompanhar a perda de peso":"Força e controle")+" · "+(variant==1?"B":"A");steps.put(step("Aqueça","5 min","Ombros, tornozelos e caminhada leve, apenas se tolerada."));List<String> keys=new ArrayList<>();if(p.place.equals("gym")){keys.add("machineRow");keys.add("machinePress");}else{keys.add(regular?"incline":"wall");keys.add("row");}if(!p.health.equals("joint"))keys.add(p.place.equals("gym")?"leg":variant==1?"hinge":"chair");if(!protect&&variant==1&&!p.goal.equals("taf"))keys.add("heel");keys.add(p.goal.equals("taf")||variant==1?"wallCore":"core");
     for(String key:keys){JSONArray move=c.getJSONObject("trainingMovements").getJSONArray(key);steps.put(step(move.getString(0),sets+" série(s) de "+(key.equals("core")||key.equals("wallCore")?"5 ativações de 5 segundos":reps+" repetições"),move.getString(1)));}if(p.frequency<=2)steps.put(step("Caminhada complementar","5 min","Ritmo leve e terreno plano, se tolerada. Pode separar da força no mesmo dia."));steps.put(step("Pausas e finalização","60–90 s entre séries; 3 min ao final","Descanse mais se precisar. Sem falha muscular. Pare com dor, inchaço ou instabilidade. Não aumente carga e volume ao mesmo tempo."));
    }
   }
   week.put(t.put("kind",kind).put("title",title).put("minutes",minutes).put("effort",effort).put("steps",steps));
  }weeks.put(week);}return weeks;
 }
}
